const F = Math.max(0, P.F);          // applied force (N)
const ang = (P.theta) * Math.PI / 180;  // angle above horizontal
const d = 8;                          // displacement (m)
const W = F * d * Math.cos(ang);      // work done by the force
// block slides along the floor, displacement d, looping
const yFloor = 0;
v.line(0, yFloor, 10, yFloor, { color: H.colors.axis, width: 2 });
const xc = 0.5 + d * (0.5 - 0.5 * Math.cos(t * 0.8));   // 0.5 .. 8.5
v.rect(xc - 0.6, yFloor, 1.2, 0.9, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
// force vector at angle theta from block
const fLen = Math.min(4, F * 0.06);
const fx = xc + fLen * Math.cos(ang), fy = yFloor + 0.45 + fLen * Math.sin(ang);
v.arrow(xc, yFloor + 0.45, fx, fy, { color: H.colors.warn, width: 4 });
// horizontal component (the part that does work)
v.arrow(xc, yFloor + 0.45, xc + fLen * Math.cos(ang), yFloor + 0.45, { color: H.colors.good, width: 2, dash: [4, 3] });
